import sys
import re

def main():
    text = sys.stdin.read()
    env = {}

    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;?\s*$')

    def evaluate(expr):
        # Translate the pseudo-code expression into a Python expression
        py = re.sub(r'\bmod\b', '%', expr)
        names = set(re.findall(r'[A-Za-z_]\w*', py))
        local = {n: env.get(n, 0) for n in names}
        return eval(py, {"__builtins__": {}}, local)

    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        # Remove trailing comments if any
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        # A line may contain several statements separated by ';'
        for stmt in line.split(';'):
            stmt = stmt.strip()
            if not stmt:
                continue
            m = assign_re.match(stmt)
            if not m:
                continue
            var, expr = m.group(1), m.group(2)
            env[var] = evaluate(expr)

    order = list("abcdefghijklmnop") + ["TMP"]
    parts = ["%s ?= %s;" % (v, env.get(v, 0)) for v in order]
    print(" ".join(parts))

if __name__ == "__main__":
    main()
